"""Complete the reviewed security statute path with article-specific cases."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'explicacoes/seguranca-privada-aplicacao-2026-10-11.json'
D={
'art-41':('Empresas de segurança e escolas informam periodicamente à PF empregados, armas, munições, veículos e contratos. O serviço orgânico presta as informações correspondentes. O transporte de valores mantém registro diário de operações.','Informação periódica e registro diário têm objetos e frequências distintos.','Não trate registro diário de operações como substituto da informação periódica à PF.','A transportadora mantém registro diário das operações e informações periódicas de frota: os dois deveres coexistem.','Mantém apenas a lista de empregados e não o registro diário de transporte: falta o dever específico do parágrafo correspondente.','O registro de operações do transporte é apenas anual? Não; o artigo exige registro diário.'),
'art-42':('Empresas de monitoramento eletrônico devem informar periodicamente à PF a relação de profissionais empregados nas atividades técnicas de instalação, operação e manutenção previstas no artigo.','É obrigação específica da categoria de monitoramento eletrônico.','Não copie automaticamente para esta relação o cadastro de armas de empresa armada do artigo anterior.','A empresa de monitoramento atualiza a lista de técnicos empregados e a apresenta à PF: cumpre o dever específico de informação.','Alega que, por não usar armas, não precisa informar seus técnicos: o art. 42 não limita o dever a empresas armadas.','A ausência de armas dispensa a informação do art. 42? Não; o dever é sobre os profissionais técnicos da empresa de monitoramento.'),
'art-43':('Contratantes de serviços de segurança privada que não sejam instituições financeiras devem fornecer à PF os dados de seus contratos quando solicitados.','Sujeito: contratante não financeiro; gatilho: solicitação da PF.','Não confunda este fornecimento sob solicitação com a informação periódica dos prestadores.','Uma empresa comercial contratante recebe solicitação da PF sobre o contrato de segurança: deve prestar os dados.','O exercício atribui a esse artigo prazo fixo anual independente de solicitação: essa periodicidade não está prevista aqui.','Qual evento aciona o dever descrito? A solicitação da PF ao contratante não financeiro.'),
'art-44':('Instituições financeiras, prestadores de segurança, serviços orgânicos e profissionais fornecem informações e documentos à PF nas condições do artigo, permitindo fiscalização de serviços, segurança e ocorrências.','A fiscalização exige cooperação documental e informação sobre ocorrências.','Não confunda informar a ocorrência à PF com dispensar outras comunicações exigidas por lei.','A PF solicita documentos sobre uma ocorrência de segurança ao prestador: a obrigação de cooperação deve ser atendida.','O prestador comunica a ocorrência, mas se recusa a produzir os documentos solicitados: informar não substitui o dever documental.','A prestação de uma informação elimina a obrigação de apresentar documentos solicitados? Não; são deveres complementares no artigo.'),
'art-45':('Cabe à Polícia Federal aplicar as penalidades administrativas por infração à lei, assegurado o processo legal. A Lei 9.784/1999 se aplica subsidiariamente ao processo administrativo.','Competência sancionadora da PF e processo administrativo.','Subsidiariedade não permite afastar regra especial do estatuto.','A PF apura infração de prestador com defesa e aplica a penalidade prevista: atua na competência do artigo.','Uma prefeitura pretende substituir a PF na aplicação das penalidades deste estatuto apenas por emitir alvará: o art. 45 atribui essa competência à PF.','Qual lei processual se aplica subsidiariamente? A Lei 9.784/1999, respeitadas as normas especiais.'),
'art-46':('Para prestadores e serviços orgânicos, o artigo prevê advertência, multa de mil a quinze mil reais e cancelamento da autorização, nas hipóteses e critérios legais. Também alcança contratantes quando expressamente previsto. A multa pode chegar ao triplo nas condições de capacidade econômica e discriminação descritas.','Não existe pena administrativa única para toda infração.','O triplo exige a hipótese legal; não é aumento automático em qualquer multa.','A PF verifica que a multa máxima é ineficaz em razão da capacidade econômica e examina a elevação admitida pelo artigo.','A empresa é pequena e não há condição legal para triplicar: não se pode aplicar o triplo apenas por preferência do fiscal.','Toda infração leva automaticamente ao cancelamento? Não; o artigo prevê espécies e critérios próprios de penalidade.'),
'art-47':('Instituições financeiras podem receber advertência, multa e interdição nos termos do artigo. A multa geral vai de dez a trinta mil reais; para cooperativas de crédito, de mil a dez mil. As regras tratam de reincidência por dependência, discriminação, regularização e plano de segurança.','Não há interdição cautelar nesta disciplina; a sanção exige o procedimento com defesa.','Plano aprovado antes da decisão final de interdição leva à conversão em multa conforme regra legal, não a perdão irrestrito.','A dependência obtém aprovação do plano antes da decisão final de interdição: aplica-se a regra de conversão prevista.','A autoridade pretende interdição cautelar sem o procedimento: o dispositivo a veda.','A multa da cooperativa tem o mesmo intervalo geral? Não; é de mil a dez mil reais, diferente de dez a trinta mil para a regra geral.'),
'art-48':('Organizar, oferecer ou contratar segurança irregular sujeita-se à multa prevista na remissão ao art. 47, II, e à cessação imediata da atividade. O dispositivo também disciplina fechamento de estabelecimento não autorizado e apreensão, com destinação do material após o procedimento administrativo e ressalvas legais.','Cessação imediata não equivale a destruição imediata dos bens apreendidos.','A capacidade econômica pode permitir elevação da multa; a destinação de material respeita o procedimento e normas específicas.','Constata-se atividade não autorizada: pode haver cessação imediata e medidas administrativas previstas.','O fiscal quer destruir imediatamente todo material apreendido, antes do procedimento: isso ignora a condição processual e as ressalvas do artigo.','A destruição de material apreendido é automática no momento da apreensão? Não; o artigo prevê procedimento administrativo e ressalvas legais.'),
'art-49':('A PF pode celebrar termo de compromisso antes do julgamento administrativo, com obrigações para corrigir irregularidades e multa por descumprimento. O termo é título executivo extrajudicial, suspende o processo enquanto cumprido e permite arquivamento após cumprimento integral.','Descumprimento retoma o procedimento e as consequências legais.','Não confunda assinatura do termo com arquivamento imediato.','A empresa firma termo, cumpre os ajustes e conclui integralmente as obrigações: pode haver arquivamento nos termos do artigo.','Assina, mas descumpre prazo essencial: não conserva automaticamente a suspensão; o processo retoma.','O processo é arquivado só pela assinatura? Não; a conclusão e o cumprimento integral das obrigações são necessários.'),
'art-50':('Organizar, prestar ou oferecer serviço de segurança privada armado, como sócio ou proprietário, sem autorização, constitui o crime específico do artigo. A pena é detenção de um a três anos e multa.','Forma armada, posição do agente e falta de autorização compõem o tipo.','Atividade desarmada irregular pode sofrer consequências administrativas; não transfira para ela automaticamente este tipo penal armado.','O proprietário oferece vigilância armada sem autorização: estão presentes os elementos descritos a serem examinados.','O serviço irregular é desarmado: a irregularidade não satisfaz, por esse fato isolado, o elemento armado do art. 50.','A pena do art. 50 é reclusão? Não; é detenção de um a três anos e multa.'),
'art-51':('O artigo institui as taxas pelos serviços da PF relacionados no anexo e disciplina seu recolhimento nos prazos e condições correspondentes.','Taxa de serviço é distinta de multa por infração.','Não invente valor: identifique o item do anexo e eventual ato oficial aplicável.','A empresa solicita autorização de funcionamento: verifica o item específico e recolhe a taxa correspondente.','A cobrança decorre de punição por irregularidade: trata-se de multa, não da taxa por serviço do anexo.','Taxa e multa têm a mesma finalidade? Não; taxa refere-se ao serviço relacionado no anexo, multa é sanção por infração.'),
'art-52':('As infrações e o procedimento seguem a disciplina da PF com garantia de defesa. A cobrança dos créditos observa o Decreto 70.235/1972 na remissão do artigo.','Apuração e defesa não se confundem com a fase de cobrança.','Não use o rito de cobrança para eliminar a defesa na apuração da infração.','Concluída a apuração com defesa, inicia-se a cobrança do crédito na forma da remissão legal.','A autoridade tenta cobrar sem observar o procedimento de apuração devido: a regra de cobrança não supre essa etapa.','A remissão sobre cobrança afasta o direito de defesa? Não; o artigo preserva as garantias procedimentais.'),
'art-53':('A PF, por intermédio do Ministério da Justiça e Segurança Pública, pode celebrar convênios com Estados para delegar parte da fiscalização e controle. Há disciplina de participação em taxas e multas, sem subdelegação e sem criar cobranças estaduais adicionais pela atividade regulada.','Delegação parcial por convênio não admite subdelegação.','Não confunda participação na receita com instituição de nova taxa estadual do estatuto.','O Estado atua na fiscalização delimitada pelo convênio com a PF.','Pretende repassar a competência recebida a outro órgão por subdelegação: a lei não autoriza essa transferência.','O Estado conveniado pode subdelegar livremente a fiscalização? Não; o artigo veda a subdelegação.'),
'art-54':('A adequação dos requisitos de escolaridade de profissionais abrangidos segue a disciplina de transição regulamentar prevista no artigo.','Transição de escolaridade precisa ser lida com os requisitos do art. 28 e a regulamentação.','Não transforme transição em dispensa permanente para todo novo ingressante.','Um profissional já atuante busca saber como adequar sua escolaridade: examina a regra de transição e a regulamentação.','Um novo candidato assume que ninguém precisa atender à escolaridade: a transição não elimina os requisitos gerais.','A transição elimina a escolaridade de todo novo candidato? Não; deve ser interpretada com os requisitos legais e a disciplina regulamentar.'),
'art-55':('O transporte internacional de valores será regulado conjuntamente pelos Ministérios da Justiça e Segurança Pública, da Fazenda, da Defesa e das Relações Exteriores.','Quatro áreas ministeriais participam da disciplina conjunta.','Não atribua a regulamentação exclusivamente à PF por ela fiscalizar o setor.','A operação pretende transportar valores internacionalmente e precisa observar a disciplina conjunta.','É operação exclusivamente doméstica: a característica internacional que aciona esta regra não está presente.','A PF sozinha recebe aqui a competência regulamentar? Não; o artigo prevê atuação conjunta dos quatro Ministérios indicados.'),
'art-56':('Armas de uso controlado apreendidas judicialmente podem ser alienadas ou adjudicadas apenas a outros prestadores de segurança privada, mediante manifestação favorável da PF, nas condições legais.','Apreensão judicial, destinatário permitido e manifestação favorável são condições relevantes.','A venda judicial não dispensa o controle da PF nem permite qualquer comprador.','Outro prestador de segurança pretende adquirir arma apreendida judicialmente e há manifestação favorável da PF: examina-se a hipótese legal.','Um particular sem essa condição pretende adquiri-la na mesma operação: não atende à restrição de destinatário.','A alienação judicial permite venda a qualquer pessoa? Não; o artigo limita os destinatários e exige manifestação favorável da PF.'),
'art-57':('Órgãos de registro empresarial comunicam à PF, no prazo de quinze dias contado do registro, os atos relacionados às atividades abrangidas, conforme o artigo.','O marco inicial é o registro do ato.','Registro empresarial não substitui autorização de segurança da PF.','Um ato empresarial é registrado e o órgão comunica à PF dentro dos quinze dias: observa o prazo.','A empresa usa o registro para começar serviço antes da autorização: a comunicação não autoriza início da atividade.','O prazo começa na primeira prestação do serviço? Não; é contado do registro do ato.'),
'art-58':('O estatuto preserva a aplicação da legislação trabalhista e os direitos decorrentes de negociação coletiva na forma prevista.','Regras de segurança e proteção trabalhista coexistem.','Autorização da PF não dispensa cumprimento de obrigações trabalhistas.','O prestador autorizado organiza a jornada observando a lei e o instrumento coletivo aplicável.','Alega que a fiscalização da PF elimina o acordo coletivo: essa conclusão contraria a preservação do artigo.','Autorização de funcionamento afasta direitos trabalhistas? Não; o estatuto preserva sua aplicação.'),
'art-59':('As atividades do Banco Central ligadas à segurança e ao transporte de moeda nacional nos termos do artigo não se submetem ao estatuto. A exceção não se estende automaticamente às empresas privadas de segurança que o Banco Central contrata.','Distinguir atividade própria do Banco Central e prestador privado contratado.','Não conceda uma imunidade geral a qualquer empresa que atenda ao Banco Central.','O Banco Central executa sua atividade própria abrangida pela exceção.','Contrata empresa privada de segurança: a empresa deve observar o estatuto conforme o artigo.','Toda contratada do Banco Central fica dispensada do estatuto? Não; a exceção não abrange automaticamente os prestadores privados contratados.'),
'art-60':('Os abrangidos dispõem do prazo máximo de três anos da publicação para adequação, salvo prazos específicos que a lei estabelece.','Regra geral de transição não substitui o cronograma específico de outro artigo.','O art. 33 possui etapas próprias; não use os três anos para apagar a etapa de 48 meses que ele prevê.','A instituição verifica um requisito sem prazo específico e consulta o limite geral de adaptação.','O requisito tem cronograma próprio no art. 33: deve aplicar esse cronograma, não substituir todas as etapas por três anos.','O prazo geral revoga os prazos específicos? Não; o próprio artigo ressalva esses prazos.'),
'art-61':('O seguro das instituições financeiras contra roubo e furto qualificado depende da prova de cumprimento das exigências legais de segurança. Contrato irregular não tem cobertura de resseguro nos termos do artigo.','Segurança exigida e contratação de seguro não são alternativas intercambiáveis.','Seguro não autoriza instituição a descumprir o plano de segurança.','A instituição comprova o atendimento às exigências para contratar o seguro previsto.','Pretende substituir a segurança exigida por uma apólice: isso não satisfaz a condição legal.','A apólice pode substituir o cumprimento das exigências de segurança? Não; sua contratação depende da comprovação prevista.'),
'art-62':('Medidas adicionais de segurança que superem o mínimo exigido podem gerar desconto no prêmio do seguro, conforme regulamentação.','Proteção adicional, desconto e disciplina regulamentar.','Não confunda desconto no prêmio com dispensa de recolher taxa à PF.','A instituição instala medidas adicionais acima do mínimo e solicita o desconto conforme a regulamentação.','Apenas cumpre o mínimo obrigatório e exige o mesmo desconto automaticamente: o artigo trata de proteção adicional.','Cumprir só o mínimo gera automaticamente o desconto? Não; a hipótese considera medidas adicionais e a regulamentação.'),
'art-63':('Atividades de proteção da aviação civil contra atos de interferência ilícita nas áreas restritas de segurança são ressalvadas na delimitação prevista. A exceção não torna toda atividade privada em aeroportos imune ao estatuto.','Objeto específico e área restrita são decisivos.','Não generalize a exclusão para vigilância de qualquer loja ou estacionamento de aeroporto.','A atividade é a proteção da aviação civil contra interferência ilícita em área restrita: examina-se a ressalva.','É vigilância de estabelecimento comercial comum no aeroporto: a localização aeroportuária, sozinha, não satisfaz a ressalva.','Todo serviço prestado em aeroporto está excluído? Não; é necessário atender ao objeto e âmbito específicos do artigo.'),
'art-64':('O transporte dos produtos controlados enumerados, como pólvora, explosivos e artigos pirotécnicos, em quantidade superior a cinquenta quilogramas exige veículos rastreados e monitorados, com escolta armada, conforme as condições legais.','A expressão é superior a 50 kg.','Exatamente 50 kg não preenche esse limite específico, sem afastar outras exigências de transporte ou controle aplicáveis.','A carga abrangida pesa 51 kg: o limite quantitativo do artigo é ultrapassado.','Pesa exatamente 50 kg: o limite superior a cinquenta não está preenchido por esse dado isolado.','Uma carga de exatamente cinquenta quilos supera o limite do artigo? Não; superior exige quantidade maior que cinquenta, ressalvadas outras regras aplicáveis.'),
'art-65':('O artigo modifica o Estatuto do Desarmamento quanto a armas das empresas de segurança, uso em serviço, registros e recarga por escolas. É norma modificadora e precisa ser estudada junto aos arts. 7º e 23 da Lei 10.826/2003 compilada.','Propriedade e controle da empresa; porte em serviço nas condições legais.','Não transforme porte funcional em permissão de uso pessoal fora do serviço; recarga depende da autorização e finalidade próprias.','O vigilante usa arma da empresa no serviço, observados os registros e controles legais.','Pretende levar a arma para uso particular após o turno: a alteração não concede essa permissão geral.','A alteração autoriza porte pessoal irrestrito fora do serviço? Não; devem ser respeitadas as condições do Estatuto do Desarmamento vigente.'),
'art-66':('Modifica a Lei 10.446/2002, incluindo infrações relacionadas a instituições financeiras e prestadores de transporte de valores nas hipóteses de atuação investigativa federal descritas. Deve ser lido com o caput e os incisos IV e VIII do art. 1º dessa lei compilada.','Investigação pela PF e competência jurisdicional federal são questões distintas.','A inclusão no rol não torna toda infração automaticamente de competência da Justiça Federal; examine repercussão e necessidade de repressão uniforme previstas.','Uma infração atende à hipótese do rol e às condições de repercussão e repressão uniforme: examina-se a atuação investigativa da PF.','Só se informa que a vítima é banco: esse fato não permite concluir automaticamente por competência jurisdicional federal.','O rol de atuação investigativa da PF resolve sozinho a competência judicial? Não; são análises jurídicas distintas.'),
'art-67':('O artigo alterou a remissão do inciso I do art. 8º da Lei 10.637/2002 para o Estatuto da Segurança Privada. É alteração de enquadramento legal em matéria de PIS/Pasep, não uma isenção geral criada para qualquer atividade de segurança.','Estude a alteração de 2024 junto à lei tributária compilada e à produção de efeitos de normas posteriores.','O texto oficial remete à LC 214/2025 e a datas próprias da transição tributária; publicação e produção de efeitos não são a mesma coisa. Não use esta unidade isoladamente para calcular tributo atual.','O aluno identifica a remissão atualizada de uma lei revogada para o novo estatuto: esse é o objeto modificador do artigo.','Interpreta a troca de remissão como dispensa total de PIS/Pasep: a alteração não contém essa isenção geral.','Atualizar a referência ao estatuto significa conceder isenção geral? Não; é necessário examinar o enquadramento e as regras tributárias compiladas, inclusive seus efeitos temporais.'),
'art-68':('Altera a remissão do inciso I do art. 10 da Lei 10.833/2003 para o Estatuto da Segurança Privada, na disciplina da Cofins. A análise atual requer a lei tributária compilada e as normas posteriores de transição, não apenas a transcrição de 2024.','Art. 67 trata de PIS/Pasep; art. 68 trata de Cofins.','A LC 214/2025 é indicada na fonte oficial com produção de efeitos própria; não confunda a existência da lei com vigência imediata de toda mudança tributária.','O exercício pede qual contribuição recebe a mudança do art. 68: é Cofins, na remissão à Lei 10.833/2003.','Troca essa contribuição por PIS/Pasep: essa é a alteração distinta do art. 67.','Qual a diferença entre os arts. 67 e 68? O art. 67 modifica a Lei do PIS/Pasep; o art. 68 modifica a Lei da Cofins.'),
'art-69':('Acrescenta o art. 183-A ao Código Penal, aumentando de um terço até o dobro as penas dos crimes do título patrimonial contra instituições financeiras e prestadores de segurança privada abrangidos.','É causa de aumento inserida no CP, não novo crime autônomo.','A unidade correta do CP é art. 183-A. A violação de direito autoral pertence ao art. 184, separado após correção de extração.','Um crime patrimonial é praticado contra instituição financeira: examina-se a causa de aumento no Código Penal atual.','O assunto é violação de direito autoral: não se usa a pena do art. 184 como se integrasse esta majorante.','O art. 69 cria um novo crime com pena de detenção? Não; insere causa de aumento nas penas dos crimes patrimoniais abrangidos.'),
'art-70':('O artigo revoga os diplomas e dispositivos enumerados, incluindo a Lei 7.102/1983 e as alterações relacionadas ao regime substituído. A lista deve ser conferida literalmente, sem estender a revogação a toda legislação de armas ou segurança.','Regime revogado não deve ser apresentado como estatuto atual da segurança privada.','Revogação e regras de adaptação são análises distintas: consultar os prazos do novo estatuto.','Uma apostila apresenta a Lei 7.102/1983 como estatuto vigente: a revogação exige atualizar a referência.','O aluno conclui que o Estatuto do Desarmamento inteiro também foi revogado: a conclusão não está na lista deste artigo.','Toda norma sobre armas foi revogada pelo art. 70? Não; ele revoga os diplomas e dispositivos expressamente enumerados.'),
'art-72':('A Lei 14.967/2024 entra em vigor na data de sua publicação, nos termos do artigo. Entrada em vigor não apaga os prazos de adequação específicos previstos no próprio estatuto.','Vigência imediata e adaptação temporal são planos distintos.','Não use o prazo geral de três anos como se adiasse a vigência de toda a lei.','O aluno procura a data de vigência e encontra a regra de publicação do art. 72.','Uma empresa tem prazo de adaptação: isso não altera a cláusula de entrada em vigor da lei.','O prazo de adequação adia toda a vigência por três anos? Não; o art. 72 estabelece vigência na publicação, com transições próprias.'),
'anexo-1':('O anexo relaciona taxas de serviços da PF, com identificação de cada serviço e valor. Autorização de funcionamento de empresa de segurança e de serviço orgânico são itens distintos; o mesmo vale para vistorias, documentos e alterações.','Na tabela: autorização de empresa, R$ 2.190; autorização de serviço orgânico, R$ 730. Conferir eventual atualização oficial do valor antes de recolher.','Taxa não é multa. Não confunda vistoria com autorização ou renovação.','O exercício pede o valor tabelado da autorização de empresa de segurança: consulte o item 3, R$ 2.190.','Pede autorização do serviço orgânico: o item 5 traz R$ 730, e não o valor da empresa prestadora.','O anexo cobra o mesmo valor de autorização para empresa e serviço orgânico? Não; os itens indicam R$ 2.190 e R$ 730, respectivamente, na tabela legal.'),
}
data=json.loads(p.read_text(encoding='utf-8'))
for key,t in D.items():
 data['units'][key]={'simples':t[0],'pontos':[t[1]],'atencao':[t[2]],'exemplo':t[3]+' Variação: '+t[4],'prova':[t[5]],'termos':[],'remissoes':[]}
data['units']['art-2']['remissoes']=['Art. 25']
for key,reference in [('art-67','art. 542, XVIII, b'),('art-68','art. 542, XXI, a')]:
 data['units'][key]['atencao'].append('ATUALIZAÇÃO COM EFEITO FUTURO: a LC 214/2025, '+reference+', prevê revogação do dispositivo tributário alterado a partir de 1º de janeiro de 2027. Na conferência de 11/10/2026, essa data ainda é futura. O art. 544, III, confirma a produção de efeitos; leia o texto compilado, inclusive a LC 227/2026, sem antecipar a revogação.')
 data['units'][key]['prova'].append('A revogação tributária prevista para janeiro de 2027 já produz esses efeitos em outubro de 2026? Não; a produção de efeitos desse ponto é futura, embora a lei complementar já tenha sido publicada.')
assert len(data['units'])==72
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('72 article-specific explanations completed')
